def compute_result(base_amount, applied_codes, all_discounts):
    final_amount_val = base_amount
    invalid_codes_val = []

    for code_val in applied_codes:
        try:
            final_amount_val -= all_discounts[code_val]
        except KeyError:
            invalid_codes_val.append(code_val)

    return {'total': final_amount_val, 'rejected': invalid_codes_val}

